<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {changedEvent,api,mutate,can,text,opts,useTask,type DTO,type Page} from './shared';import {useForm} from './forms';import type {Field} from './TaskForm.vue';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';import ConnectionsPanel from './ConnectionsPanel.vue';
const route=useRoute(),{busy,error,notice,run}=useTask(),{form,open}=useForm(),tab=ref(String(route.query.tab??'ledger')),rows=ref<DTO<'Stage2LedgerView'>[]>([]),selected=ref<DTO<'Stage2LedgerView'>>(),periods=ref<DTO<'Stage2PeriodView'>[]>([]),expenses=ref<DTO<'Stage2ExpenseView'>[]>([]),summary=ref<DTO<'Stage2MoneySummary'>[]>([]),names=ref<Record<string,string>>({}),page=ref(1),total=ref(0),more=ref(false),periodPage=ref(1),periodTotal=ref(0),periodMore=ref(false),expensePage=ref(1),expenseTotal=ref(0),expenseMore=ref(false);
const currencies=['CNY','USD','EUR','GBP','HKD','JPY','SGD','AUD','CAD','CHF'];
async function details(){if(!selected.value)return;selected.value=await api.get<DTO<'Stage2LedgerView'>>('/subscriptions/'+selected.value.id);const [p,e]=await Promise.all([api.get<Page<DTO<'Stage2PeriodView'>>>(`/subscriptions/${selected.value.id}/periods?page=${periodPage.value}`),api.get<Page<DTO<'Stage2ExpenseView'>>>(`/subscriptions/${selected.value.id}/expenses?page=${expensePage.value}`)]);periods.value=p.items;periodTotal.value=p.pagination.total;periodMore.value=p.pagination.has_next;expenses.value=e.items;expenseTotal.value=e.pagination.total;expenseMore.value=e.pagination.has_next;}
async function load(){if(!can('finance.read'))return;await run(async()=>{const [l,s]=await Promise.all([api.get<Page<DTO<'Stage2LedgerView'>>>('/subscriptions?page='+page.value),api.get<DTO<'Stage2SummaryView'>>('/expense-summary')]);rows.value=l.items;total.value=l.pagination.total;more.value=l.pagination.has_next;summary.value=s.items;await Promise.all(rows.value.map(async row=>{const r=await api.get<DTO<'ResourceView'>>('/resources/'+row.resource_id);names.value[row.resource_id]=r.name;}));if(route.query.resource&&!selected.value)selected.value=rows.value.find(r=>r.resource_id===route.query.resource);await details();});}onMounted(load);
function ledger(row?:DTO<'Stage2LedgerView'>){const fields:Field[]=[...(!row?[{key:'resource_id',label:'订阅或服务资源',endpoint:'/resources',required:true}]:[]),{key:'plan',label:'套餐',initial:row?.plan??''},{key:'seats_total',label:'总席位',type:'number',min:0,initial:row?.seats_total?.toString()??''},{key:'seats_assigned',label:'已分配席位',type:'number',min:0,initial:row?.seats_assigned?.toString()??''},{key:'billing_cycle',label:'计费周期',required:true,options:opts(['month','year','custom']),initial:row?.billing_cycle??'month'},{key:'reminder_days',label:'到期提醒天数',required:true,initial:(row?.reminder_days??[30,7,1]).join(','),hint:'不重复的 0—365 天，逗号分隔'},...(row?[{key:'reason',label:'修订原因',required:true,type:'textarea'}]:[])];open({title:row?'维护订阅台账':'建立订阅台账',fields,onSubmit:async v=>{const payload={plan:v.plan||null,seats_total:v.seats_total?Number(v.seats_total):null,seats_assigned:v.seats_assigned?Number(v.seats_assigned):null,billing_cycle:v.billing_cycle,reminder_days:v.reminder_days.split(/[,，]/).map(Number),...(row?{expected_version:row.version,reason:v.reason}:{resource_id:v.resource_id})};await mutate(row?'/subscriptions/'+row.id:'/subscriptions',payload,row?'PATCH':'POST');await load();}});}
function period(){const l=selected.value!;open({title:'新增订阅周期 / 续期',description:'新增完整周期并保留历史；金额可以暂缺，币种必须明确。',fields:[{key:'starts_on',label:'开始日',type:'date',required:true},{key:'ends_on',label:'结束日',type:'date',required:true},{key:'planned_amount',label:'计划金额',type:'number',min:0},{key:'currency',label:'币种',required:true,options:opts(currencies),initial:'CNY'},{key:'source',label:'依据来源',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/subscriptions/${l.id}/periods`,{...v,planned_amount:v.planned_amount||null,expected_version:l.version});await load();}});}
function expense(correct?:DTO<'Stage2ExpenseView'>){const l=selected.value!;open({title:correct?'更正费用记录':'新增费用记录',description:correct?'原记录须已作废，新增更正记录将引用原记录。':'预算和实际支出分开记录；不同币种不会相加。',fields:[{key:'amount',label:'金额',type:'number',min:0,required:true,initial:correct?.amount},{key:'currency',label:'币种',required:true,options:opts(currencies),initial:correct?.currency??'CNY'},{key:'kind',label:'费用口径',required:true,options:opts(['actual','budget']),initial:correct?.kind??'actual'},{key:'recorded_on',label:'记账日',type:'date',required:true},{key:'period_id',label:'关联周期（可选）',options:periods.value.filter(p=>!p.void_reason).map(p=>({value:p.id,label:`${p.starts_on} — ${p.ends_on}`}))},{key:'source',label:'依据来源',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/subscriptions/${l.id}/expenses`,{...v,period_id:v.period_id||null,expected_version:l.version,...(correct?{corrects_entry_id:correct.id}:{})});await load();}});}
function voidEntry(e:DTO<'Stage2PeriodView'>|DTO<'Stage2ExpenseView'>,isPeriod:boolean){open({title:'作废'+(isPeriod?'周期':'费用记录'),description:'保留原始记录与作废原因，不直接覆盖历史。',fields:[{key:'reason',label:'作废原因',type:'textarea',required:true}],onSubmit:async v=>{await mutate(`/${isPeriod?'subscription-periods':'expenses'}/${e.id}/actions/void`,{expected_version:e.version,...v});await load();}});}
</script>
<template><header class="page-heading"><div><h1>订阅与费用</h1><p>人工台账、费用记录与平台同步各有来源，不混算不同口径或币种。</p></div><button v-if="tab==='ledger'&&can('finance.write')" class="btn-primary" @click="ledger()">建立台账</button></header><section class="feishu-section"><nav class="flex overflow-x-auto border-b"><button class="task-tab" :class="tab==='ledger'?'task-tab-active':''" @click="tab='ledger'">订阅台账</button><button v-if="can('integration.manage')" class="task-tab" :class="tab==='connections'?'task-tab-active':''" @click="tab='connections'">平台连接与采集</button><button v-if="can('finance.read')" class="task-tab" :class="tab==='summary'?'task-tab-active':''" @click="tab='summary'">费用汇总</button></nav><ConnectionsPanel v-if="tab==='connections'&&can('integration.manage')"/><template v-else-if="can('finance.read')"><PageState :busy="busy" :error="error" :notice="notice" @retry="load"/><template v-if="tab==='ledger'"><div class="admin-table-scroll"><table class="feishu-table min-w-[620px]"><thead><tr><th>资源 / 套餐</th><th>当前周期</th><th>席位</th><th>计划金额</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><button class="text-link font-medium" @click="selected=r;periodPage=1;expensePage=1;run(details)">{{names[r.resource_id]??'订阅资源'}}</button><p class="mt-1 text-gray-500">{{r.plan??'未填套餐'}} · {{text(r.billing_cycle)}}</p></td><td>{{r.current_period?`${r.current_period.starts_on} — ${r.current_period.ends_on}`:'尚无有效周期'}}</td><td>{{r.seats_assigned??'—'}} / {{r.seats_total??'—'}}<p class="mt-1 text-gray-500">已确认使用人 {{r.active_users}}</p></td><td>{{r.current_period?.planned_amount!==null&&r.current_period?.planned_amount!==undefined?r.current_period.currency+' '+r.current_period.planned_amount:'未记录'}}</td><td><button v-if="can('finance.write')" class="btn-ghost text-xs" @click="ledger(r)">维护</button><RouterLink :to="'/resources/'+r.resource_id" class="text-link">资源</RouterLink></td></tr></tbody></table></div><PageState :empty="!rows.length&&!busy"/><Pager :page="page" :total="total" :more="more" @change="page=$event;load()"/><div v-if="selected" class="border-t border-gray-200 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="text-sm font-medium">{{names[selected.resource_id]??'订阅'}} · 周期与费用</h2><div v-if="can('finance.write')" class="flex gap-2"><button class="btn-secondary" @click="period">新增周期 / 续期</button><button class="btn-secondary" @click="expense()">新增费用</button><button class="btn-ghost" :disabled="busy" @click="run(async()=>{await mutate('/reminders/actions/refresh');changedEvent();notice='已重新核对到期提醒。'})">核对提醒</button></div></div><h3 class="mb-2 mt-4 text-xs font-medium">周期历史</h3><div v-for="p in periods" :key="p.id" class="flex flex-wrap justify-between gap-2 border-b py-3 text-xs"><div>{{p.starts_on}} — {{p.ends_on}} · {{p.currency}} {{p.planned_amount??'金额暂缺'}}<p class="mt-1 text-gray-500">{{p.source}} {{p.void_reason?'· 作废：'+p.void_reason:''}}</p></div><button v-if="!p.void_reason&&can('finance.write')" class="text-link" @click="voidEntry(p,true)">作废</button></div><Pager :page="periodPage" :total="periodTotal" :more="periodMore" @change="periodPage=$event;run(details)"/><h3 class="mb-2 mt-4 text-xs font-medium">费用记录</h3><div v-for="e in expenses" :key="e.id" class="flex flex-wrap justify-between gap-2 border-b py-3 text-xs"><div><strong>{{e.currency}} {{e.amount}}</strong> · {{text(e.kind)}} · {{e.recorded_on}}<p class="mt-1 text-gray-500">{{e.source}} {{e.void_reason?'· 作废：'+e.void_reason:''}} {{e.corrects_entry_id?'· 更正历史记录':''}}</p></div><button v-if="can('finance.write')" class="text-link" @click="e.void_reason?expense(e):voidEntry(e,false)">{{e.void_reason?'新增更正':'作废'}}</button></div><Pager :page="expensePage" :total="expenseTotal" :more="expenseMore" @change="expensePage=$event;run(details)"/></div></template><div v-else-if="tab==='summary'" class="p-4"><p class="mb-3 text-xs text-gray-500">按币种、月份与预算 / 实际分类统计。未做汇率折算，作废记录不计入。</p><div class="admin-table-scroll"><table class="feishu-table"><thead><tr><th>月份</th><th>币种</th><th>口径</th><th>金额</th></tr></thead><tbody><tr v-for="(s,i) in summary" :key="i"><td>{{s.period}}</td><td>{{s.currency}}</td><td>{{text(s.kind)}}</td><td>{{s.amount}}</td></tr></tbody></table></div></div></template><p v-else class="p-5 text-sm text-gray-500">当前账号没有费用查看权限。可在资源详情查看非金额的订阅摘要。</p></section><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
